y/ncmeta/pulls/13\",\"html_url\":\"https://github.com/hypertidy/ncmeta/pull/13\",\"diff_url\":\"https://github.com/hypertidy/ncmeta/pull/13.diff\",\"patch_url\":\"https://github.com/hypertidy/ncmeta/pull/13.patch\",\"merged_at\":\"2018-12-26T22:12:22Z\"},\"body\":\"Would you like an option like \\\"add_name = FALSE\\\" that would maintain the old behavior? This isn't backward compatible in its current form.\",\"closed_by\":{\"login\":\"mdsumner\",\"id\":4107631,\"node_id\":\"MDQ6VXNlcjQxMDc2MzE=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/4107631?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/mdsumner\",\"html_url\":\"https://github.com/mdsumner\",\"followers_url\":\"https://api.github.com/users/mdsumner/followers\",\"following_url\":\"https://api.github.com/users/mdsumner/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/mdsumner/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/mdsumner/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/mdsumner/subscriptions\",\"organizations_url\":\"https://api.github.com/users/mdsumner/orgs\",\"repos_url\":\"https://api.github.com/users/mdsumner/repos\",\"events_url\":\"https://api.github.com/users/mdsumner/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/mdsumner/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"reactions\":{\"url\":\"ghrepos/hypertidy/ncmeta/issues/13/reactions\",\"total_count\":0,\"+1\":0,\"-1\":0,\"laugh\":0,\"hooray\":0,\"confused\":0,\"heart\":0,\"rocket\":0,\"eyes\":0},\"timeline_url\":\"ghrepos/hypertidy/ncmeta/issues/13/timeline\",\"performed_via_github_app\":null,\"state_reason\":null},{\"url\":\"ghrepos/hypertidy/ncmeta/issues/12\",\"repository_url\":\"ghrepos/hypertidy/ncmeta\",\"labels_url\":\"ghrepos/hypertidy/ncmeta/issues/12/labels{/name}\",\"comments_url\":\"ghrepos/hypertidy/ncmeta/issues/12/comments\",\"events_url\":\"ghrepos/hypertidy/ncmeta/issues/12/events\",\"html_url\":\"https://github.com/hypertidy/ncmeta/issues/12\",\"id\":394074880,\"node_id\":\"MDU6SXNzdWUzOTQwNzQ4ODA=\",\"number\":12,\"title\":\"Should nc_att() include the attribute name?\",\"user\":{\"login\":\"dblodgett-usgs\",\"id\":1492803,\"node_id\":\"MDQ6VXNlcjE0OTI4MDM=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/1492803?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/dblodgett-usgs\",\"html_url\":\"https://github.com/dblodgett-usgs\",\"followers_url\":\"https://api.github.com/users/dblodgett-usgs/followers\",\"following_url\":\"https://api.github.com/users/dblodgett-usgs/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/dblodgett-usgs/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/dblodgett-usgs/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/dblodgett-usgs/subscriptions\",\"organizations_url\":\"https://api.github.com/users/dblodgett-usgs/orgs\",\"repos_url\":\"https://api.github.com/users/dblodgett-usgs/repos\",\"events_url\":\"https://api.github.com/users/dblodgett-usgs/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/dblodgett-usgs/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"labels\":[],\"state\":\"closed\",\"locked\":false,\"assignees\":[],\"milestone\":null,\"comments\":2,\"created_at\":\"2018-12-26T03:44:15Z\",\"updated_at\":\"2018-12-26T22:12:22Z\",\"closed_at\":\"2018-12-26T22:12:22Z\",\"assignee\":null,\"author_association\":\"CONTRIBUTOR\",\"issue_field_values\":[],\"type\":null,\"active_lock_reason\":null,\"sub_issues_summary\":{\"total\":0,\"completed\":0,\"percent_completed\":0},\"issue_dependencies_summary\":{\"blocked_by\":0,\"total_blocked_by\":0,\"blocking\":0,\"total_blocking\":0},\"body\":\"I'm seeing `[1] \\\"attribute\\\" \\\"variable\\\"  \\\"value\\\"` where attribute is numeric instead of character unless you request by character in which case it comes back character. \\r\\n\\r\\nIt would be pretty useful to get the attribute name rather than the index to work with standard `cf` attributes. Would that be useful to you too? \\r\\n\\r\\nStarting to look at the code I am puttering around in nc_att adding the name and see two ways this could be done now. Since you've already got the value column as a list column, we could make it a named list. \\r\\ni.e. now I see something like:\\r\\n```\\r\\n> a$value\\r\\n[[1]]\\r\\n[1] \\\"Chlorophyll Concentration, OCI Algorithm\\\"\\r\\n```\\r\\n\\r\\nand it would better as?\\r\\n```\\r\\n> t$value\\r\\n$long_name\\r\\n[1] \\\"Chlorophyll Concentration, OCI Algorithm\\\"\\r\\n```\\r\\n\\r\\nOr we could modify the returned tibble so it has an \\\"id\\\" and a \\\"name\\\" column. The big issue now is that attributes can be requested by id or by name -- which is fine from a request point of view, but results in different kinds of output in the \\\"attribute\\\" column of the current output.\\r\\n\\r\\ne.g. try this:\\r\\n```\\r\\nf <- system.file(\\\"extdata\\\", \\\"S2008001.L3m_DAY_CHL_chlor_a_9km.nc\\\", package = \\\"ncmeta\\\")\\r\\nnc_att(f, 0, 0)\\r\\nnc_att(f, \\\"chlor_a\\\", \\\"long_name\\\")\\r\\n```\\r\\n\\r\\nI started implementing a solution that does this:\\r\\n```\\r\\n> f <- system.file(\\\"extdata\\\", \\\"S2008001.L3m_DAY_CHL_chlor_a_9km.nc\\\", package = \\\"ncmeta\\\")\\r\\n> nc_att(f, 0, 0)\\r\\n# A tibble: 1 x 4\\r\\n     id name      variable value    \\r\\n* <dbl> <chr>        <dbl> <list>   \\r\\n1     0 long_name        0 <chr [1]>\\r\\n> nc_att(f, \\\"chlor_a\\\", \\\"long_name\\\")\\r\\n# A tibble: 1 x 4\\r\\n     id name      variable value    \\r\\n* <dbl> <chr>     <chr>    <list>   \\r\\n1     0 long_name chlor_a  <chr [1]>\\r\\n```\\r\\n\\r\\nAt the end of the day, I guess it comes down to how one would want to use the output. If the intention is for that \\\"attribute\\\" column to be used as a key to the semantics of the requester, I'd say leave it the way it is. If it's mean to be an identifier for the attribute, it's ambiguous and it should be changed to be \\\"id\\\" and \\\"name\\\"?\\r\\n\\r\\nI'd be happy to implement and PR a solution here depending what you think would be most useful and unintrusive. Thinking I can probably contribute a few things here that I'll use in some work I'm doing that also uses `stars` so getting on the same page re: your vision would be helpful.\\r\\n\\r\\nCheers! \\r\\n\",\"closed_by\":{\"login\":\"mdsumner\",\"id\":4107631,\"node_id\":\"MDQ6VXNlcjQxMDc2MzE=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/4107631?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/mdsumner\",\"html_url\":\"https://github.com/mdsumner\",\"followers_url\":\"https://api.github.com/users/mdsumner/followers\",\"following_url\":\"https://api.github.com/users/mdsumner/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/mdsumner/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/mdsumner/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/mdsumner/subscriptions\",\"organizations_url\":\"https://api.github.com/users/mdsumner/orgs\",\"repos_url\":\"https://api.github.com/users/mdsumner/repos\",\"events_url\":\"https://api.github.com/users/mdsumner/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/mdsumner/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"reactions\":{\"url\":\"ghrepos/hypertidy/ncmeta/issues/12/reactions\",\"total_count\":0,\"+1\":0,\"-1\":0,\"laugh\":0,\"hooray\":0,\"confused\":0,\"heart\":0,\"rocket\":0,\"eyes\":0},\"timeline_url\":\"ghrepos/hypertidy/ncmeta/issues/12/timeline\",\"performed_via_github_app\":null,\"state_reason\":\"completed\",\"pinned_comment\":null},{\"url\":\"ghrepos/hypertidy/ncmeta/issues/11\",\"repository_url\":\"ghrepos/hypertidy/ncmeta\",\"labels_url\":\"ghrepos/hypertidy/ncmeta/issues/11/l