79.9792 ;\\r\\n                :geospatial_lat_units = \\\"degrees_north\\\" ;\\r\\n                :geospatial_lon_units = \\\"degrees_east\\\" ;\\r\\n                :geospatial_lon_resolution = 0.04166667 ;\\r\\n                :geospatial_lat_resolution = 0.04166667 ;\\r\\n                :spatialResolution = \\\"4.6 km\\\" ;\\r\\n                :data_bins = 154831 ;\\r\\n                :percent_data_bins = 0.6515996 ;\\r\\n                :units = \\\"angstrom:,aot_869:,Rrs_412:sr^-1,Rrs_443:sr^-1,Rrs_469:sr^-1,Rrs_488:sr^-1,Rrs_531:sr^-1,Rrs_547:sr^-1,Rrs_555:sr^-1,Rrs_645:sr^-1,Rrs_667:sr^-1,Rrs_678:sr^-1\\\" ;\\r\\n                :binning_scheme = \\\"Integerized Sinusoidal Grid\\\" ;\\r\\n                :project = \\\"Ocean Biology Processing Group (NASA/GSFC/OBPG)\\\" ;\\r\\n                :institution = \\\"NASA Goddard Space Flight Center, Ocean Ecology Laboratory, Ocean Biology Processing Group\\\" ;\\r\\n                :standard_name_vocabulary = \\\"NetCDF Climate and Forecast (CF) Metadata Conventions\\\" ;\\r\\n                :Metadata_Conventions = \\\"Unidata Dataset Discovery v1.0\\\" ;\\r\\n                :Conventions = \\\"CF-1.6, Unidata Dataset Discovery v1.0\\\" ;\\r\\n                :naming_authority = \\\"gov.nasa.gsfc.sci.oceandata\\\" ;\\r\\n                :id = \\\"A2002184.L3b_DAY_RRS.nc/L3/A2002184.L3b_DAY_RRS.nc\\\" ;\\r\\n                :license = \\\"http://science.nasa.gov/earth-science/earth-science-data/data-information-policy/\\\" ;\\r\\n                :creator_name = \\\"NASA/GSFC/OBPG\\\" ;\\r\\n                :publisher_name = \\\"NASA/GSFC/OBPG\\\" ;\\r\\n                :creator_email = \\\"data@oceancolor.gsfc.nasa.gov\\\" ;\\r\\n                :publisher_email = \\\"data@oceancolor.gsfc.nasa.gov\\\" ;\\r\\n                :creator_url = \\\"http://oceandata.sci.gsfc.nasa.gov\\\" ;\\r\\n                :publisher_url = \\\"http://oceandata.sci.gsfc.nasa.gov\\\" ;\\r\\n                :processing_level = \\\"L3 Binned\\\" ;\\r\\n                :cdm_data_type = \\\"point\\\" ;\\r\\n                :identifier_product_doi_authority = \\\"http://dx.doi.org\\\" ;\\r\\n                :identifier_product_doi = \\\"10.5067/AQUA/MODIS_OC.2014.0\\\" ;\\r\\n                :keywords = \\\"Oceans > Ocean Chemistry > Chlorophyll; Oceans > Ocean Optics > Ocean Color\\\" ;\\r\\n                :keywords_vocabulary = \\\"NASA Global Change Master Directory (GCMD) Science Keywords\\\" ;\\r\\n```\\r\\n\\r\\nncdf4 can't touch it, making much the same assumption as tidync currently does: \\r\\n\\r\\n```\\r\\nncdf4::nc_open(l3_file)\\r\\nError in ncvar_type_to_string(rv$precint) : \\r\\n  Error, unrecognized type code of variable supplied: -1\\r\\n```\\r\\n\",\"closed_by\":{\"login\":\"mdsumner\",\"id\":4107631,\"node_id\":\"MDQ6VXNlcjQxMDc2MzE=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/4107631?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/mdsumner\",\"html_url\":\"https://github.com/mdsumner\",\"followers_url\":\"https://api.github.com/users/mdsumner/followers\",\"following_url\":\"https://api.github.com/users/mdsumner/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/mdsumner/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/mdsumner/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/mdsumner/subscriptions\",\"organizations_url\":\"https://api.github.com/users/mdsumner/orgs\",\"repos_url\":\"https://api.github.com/users/mdsumner/repos\",\"events_url\":\"https://api.github.com/users/mdsumner/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/mdsumner/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"reactions\":{\"url\":\"ghrepos/hypertidy/ncmeta/issues/3/reactions\",\"total_count\":0,\"+1\":0,\"-1\":0,\"laugh\":0,\"hooray\":0,\"confused\":0,\"heart\":0,\"rocket\":0,\"eyes\":0},\"timeline_url\":\"ghrepos/hypertidy/ncmeta/issues